INSERT INTO agent_workflows (user_id, agent_key, workflow_key, name, description, markdown_content, steps, is_enabled)
VALUES
-- /onboard — Foundation Setup (3 steps)
(
  NULL,
  'vibey',
  'onboard',
  'Onboard',
  'Set up your foundational marketing assets — offer, audience, and brand identity — in one conversation.',
  E'You are running the Onboard workflow. This sets up the user''s foundational marketing assets.\n\nThe offer comes first because everything else derives from it. The avatar is built from the offer''s buyer context. The theme is designed to resonate with both the offer positioning and the audience.\n\nFollow the steps below in order. For each step, read the referenced skill file before executing.\n\n## Steps\n\n### Step 1: Craft Your Core Offer\n**Skill:** `offer-builder` (read `skills/offer-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "Let''s start with what you sell. What''s your product or service, and what problem does it solve?"\n\nRun the full 5-step offer pipeline: product analysis, power offer statement, buyer persona, ICP analysis, competitive edge.\n\n### Step 2: Discover Your Audience\n**Skill:** `avatar-builder` (read `skills/avatar-builder/SKILL.md`)\n**Requires input:** No\n\nBuild a deep psychological buyer persona based on the offer — demographics, pain points, desires, objections, transformation.\n\n### Step 3: Set Up Brand Identity\n**Skill:** `theme-builder` (read `skills/theme-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "Offer and audience are locked in. Now let''s nail your brand. Do you have a website I can pull your brand from, or should I design one based on your industry?"\n\nDefine colors, fonts, voice, logo, and product images — informed by the offer positioning and audience.\n\n---\n\nAfter completing all 3 steps, present a summary card showing what was created: offer (what they sell + power offer statement), avatar (who they sell to), and theme (colors + fonts + voice). Then suggest next steps: "You''re ready to build. Try `/campaign_builder` to create your first full campaign, or ask me to build a funnel, emails, or content individually."',
  '[
    {"order":1,"key":"craft-offer","name":"Craft Your Core Offer","skill_key":"offer-builder","requires_input":true,"input_prompt":"Let''s start with what you sell. What''s your product or service, and what problem does it solve?","description":"5-step offer pipeline: product analysis, power offer statement, buyer persona, ICP analysis, competitive edge"},
    {"order":2,"key":"discover-audience","name":"Discover Your Audience","skill_key":"avatar-builder","requires_input":false,"description":"Build a deep psychological buyer persona based on the offer — demographics, pain points, desires, objections, transformation"},
    {"order":3,"key":"setup-brand","name":"Set Up Brand Identity","skill_key":"theme-builder","requires_input":true,"input_prompt":"Offer and audience are locked in. Now let''s nail your brand. Do you have a website I can pull your brand from, or should I design one based on your industry?","description":"Define colors, fonts, voice, logo, and product images — informed by the offer positioning and audience"}
  ]'::jsonb,
  true
),

-- /campaign_builder — Full Campaign Build (7 steps)
(
  NULL,
  'vibey',
  'campaign-builder',
  'Campaign Builder',
  'Build a complete marketing campaign — offer, audience, brand, lead magnet, funnel, emails, and social content.',
  E'You are running the Campaign Builder workflow. This builds a complete marketing campaign.\n\nIMPORTANT: Before starting each step, check if the asset already exists in this campaign (use `vibey_backend` list actions). If it does, show the user what exists and ask if they want to use it or rebuild it. Skip steps where assets already exist unless the user wants to redo them.\n\nBetween each step, give the user a progress update: "Step X/7 complete. [Asset] created. Moving to [next step]..."\n\nFollow the steps below in order. For each step, read the referenced skill file before executing.\n\n## Steps\n\n### Step 1: Craft Your Offer\n**Skill:** `offer-builder` (read `skills/offer-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "Let''s start with what you sell. What''s your product or service, and what problem does it solve?"\n\n5-step offer pipeline — skip if offer already exists in this campaign.\n\n### Step 2: Discover Your Audience\n**Skill:** `avatar-builder` (read `skills/avatar-builder/SKILL.md`)\n**Requires input:** No\n\nBuild buyer persona from the offer — skip if avatar already exists in this campaign.\n\n### Step 3: Set Up Brand Identity\n**Skill:** `theme-builder` (read `skills/theme-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "Offer and audience are set. Do you have a website I can pull your brand from, or should I design it from scratch?"\n\nDefine colors, fonts, voice — skip if theme already exists in this campaign.\n\n### Step 4: Create Lead Magnet\n**Skill:** `lead-magnet-builder` (read `skills/lead-magnet-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "What type of free resource would attract your audience? (guide, checklist, cheat sheet, workbook, case study, toolkit)"\n\nCreate a downloadable lead magnet that showcases expertise and captures leads.\n\n### Step 5: Build Landing Page & Funnel\n**Skill:** `funnel-builder` (read `skills/funnel-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "What kind of page do you need? (opt-in page for the lead magnet, full sales page, webinar registration, or product page)"\n\nBuild a high-converting landing page with the theme, offer copy, and lead magnet integration.\n\n### Step 6: Write Email Sequence\n**Skill:** `email-sequence-builder` (read `skills/email-sequence-builder/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "What should happen after someone opts in? (welcome + nurture series, launch sequence, or post-purchase flow)"\n\nCreate automated email sequence that nurtures leads from the funnel.\n\n### Step 7: Create Social Content\n**Skill:** `social-content-builder` (read `skills/social-content-builder/SKILL.md`)\n**Requires input:** No\n\nCreate exactly 4 posts — 2 for LinkedIn and 2 for Instagram. The LinkedIn posts should be professional/educational, the Instagram posts should be visual/engaging. All 4 should promote the campaign assets (offer, funnel, lead magnet) using the avatar''s language and pain points, styled with the brand voice from the theme.\n\n---\n\nAfter all 7 steps, present a campaign summary showing every asset created with links/previews. Then suggest: "Your campaign is ready. Use `/launch` to publish, or ask me to tweak any individual piece."',
  '[
    {"order":1,"key":"craft-offer","name":"Craft Your Offer","skill_key":"offer-builder","requires_input":true,"input_prompt":"Let''s start with what you sell. What''s your product or service, and what problem does it solve?","description":"5-step offer pipeline — skip if offer already exists in this campaign"},
    {"order":2,"key":"discover-audience","name":"Discover Your Audience","skill_key":"avatar-builder","requires_input":false,"description":"Build buyer persona from the offer — skip if avatar already exists in this campaign"},
    {"order":3,"key":"setup-brand","name":"Set Up Brand Identity","skill_key":"theme-builder","requires_input":true,"input_prompt":"Offer and audience are set. Do you have a website I can pull your brand from, or should I design it from scratch?","description":"Define colors, fonts, voice — skip if theme already exists in this campaign"},
    {"order":4,"key":"build-lead-magnet","name":"Create Lead Magnet","skill_key":"lead-magnet-builder","requires_input":true,"input_prompt":"What type of free resource would attract your audience? (guide, checklist, cheat sheet, workbook, case study, toolkit)","description":"Create a downloadable lead magnet that showcases expertise and captures leads"},
    {"order":5,"key":"build-funnel","name":"Build Landing Page & Funnel","skill_key":"funnel-builder","requires_input":true,"input_prompt":"What kind of page do you need? (opt-in page for the lead magnet, full sales page, webinar registration, or product page)","description":"Build a high-converting landing page with the theme, offer copy, and lead magnet integration"},
    {"order":6,"key":"build-emails","name":"Write Email Sequence","skill_key":"email-sequence-builder","requires_input":true,"input_prompt":"What should happen after someone opts in? (welcome + nurture series, launch sequence, or post-purchase flow)","description":"Create automated email sequence that nurtures leads from the funnel"},
    {"order":7,"key":"create-social-content","name":"Create Social Content","skill_key":"social-content-builder","requires_input":false,"description":"Create 4 social posts: 2 LinkedIn posts + 2 Instagram posts — promoting the offer, funnel, and lead magnet using avatar language and brand voice"}
  ]'::jsonb,
  true
),

-- /launch — Launch & Activate (4 steps)
(
  NULL,
  'vibey',
  'launch',
  'Launch',
  'Review your campaign assets, fill any gaps, publish ads to Meta, and go live.',
  E'You are running the Launch workflow. This takes an existing campaign and pushes it live.\n\nFollow the steps below in order. For each step, read the referenced skill file (if any) before executing.\n\n## Steps\n\n### Step 1: Review Campaign Assets\n**Requires input:** Yes\n**Ask user:** "Let me review what you have. Which campaign are we launching?"\n\nUse `vibey_backend` to list all assets in the campaign. Check for: theme, avatar, offer, funnel, email sequence, lead magnet, ad creatives. Present a checklist to the user showing what exists and what''s missing.\n\n### Step 2: Fill the Gaps\n**Requires input:** Yes\n**Ask user:** "Here''s what''s missing for a complete launch: [list]. Want me to build these now, or skip and launch with what we have?"\n\nIf assets are missing, offer to build them using the relevant skills. If the user says skip, proceed with what''s available. If nothing critical exists (no offer, no funnel), recommend running `/campaign_builder` instead and stop.\n\n### Step 3: Publish Ads to Meta\n**Skill:** `meta-publisher` (read `skills/meta-publisher/SKILL.md`)\n**Requires input:** Yes\n**Ask user:** "Ads are ready. Let''s connect your Meta account and publish. Which ad account should we use?"\n\nOnly proceed to Meta publishing if ad creatives exist. Use the meta-publisher skill to guide the user through account connection and publishing.\n\n### Step 4: Launch Summary & Next Steps\n**Requires input:** No\n\nPresent what''s live: funnel URL, active ads, email automation status. Suggest monitoring plan and optimization cadence. Suggest checking back in 48-72 hours to review early performance.',
  '[
    {"order":1,"key":"review-assets","name":"Review Campaign Assets","skill_key":null,"requires_input":true,"input_prompt":"Let me review what you have. Which campaign are we launching?","description":"Inventory check — list all existing assets and identify gaps"},
    {"order":2,"key":"build-missing","name":"Fill the Gaps","skill_key":null,"requires_input":true,"input_prompt":"Here''s what''s missing for a complete launch: [list]. Want me to build these now, or skip and launch with what we have?","description":"Build any missing assets using the appropriate skills — dynamic based on the review"},
    {"order":3,"key":"publish-ads","name":"Publish Ads to Meta","skill_key":"meta-publisher","requires_input":true,"input_prompt":"Ads are ready. Let''s connect your Meta account and publish. Which ad account should we use?","description":"Publish ad creatives to Meta — connect account, select page, configure campaign, go live"},
    {"order":4,"key":"launch-summary","name":"Launch Summary & Next Steps","skill_key":null,"requires_input":false,"description":"Present what''s live: funnel URL, active ads, email automation status. Suggest monitoring plan and optimization cadence."}
  ]'::jsonb,
  true
);
